private int
toomany(struct magic_set *ms, const char *name, uint16_t num)
{
        if (ms->flags & MAGIC_MIME)
                return 1;
        if (file_printf(ms, ", too many %s (%u)", name, num) == -1)
                return -1;
        return 1;
}

private uint16_t
getu16(int swap, uint16_t value)
{
        union {
                uint16_t ui;
                char c[2];
        } retval, tmpval;

        if (swap) {
                tmpval.ui = value;

                retval.c[0] = tmpval.c[1];
